(()=>{const el=document.getElementById('deploymentDataStatus');if(!el)return;const integrators=location.pathname.includes('integrators'),url=integrators?'./integrators-data.json':'./data/performance.json';Promise.all([fetch(url,{cache:'no-store'}),fetch('./api/health',{cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null)]).then(([r,h])=>{el.dataset.workerConnected=String(h?.storage==='D1');return r}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{const through=integrators?d.dataEndsAt:d.meta?.through,checked=integrators?d.generatedAt:d.meta?.retrievedAt;if(!through)throw Error();const stale=Date.now()-Date.parse(through+'T23:59:59Z')>2*86400000;el.textContent=`${stale?'Stale saved records':'Latest available saved records'} through ${through} UTC. Retrieved ${checked?.replace('T',' ').slice(0,19)||'at an unknown time'} UTC. ${el.dataset.workerConnected==='true'?'Data backend connected; see source health for refresh results.':'Automatic Cloudflare refresh is not activated.'} Issuance, burns and wallet coverage may end earlier; unavailable values remain missing.`;}).catch(()=>{el.textContent='Verified data is unavailable. No current values are shown.'})})();
